Function that executes immediately after definition.

```javascript
(function() {
  console.log("IIFE executed");
})();
```

Transforming function with multiple arguments into sequence of functions with single argument.

```javascript
const add = a => b => a + b;
const add5 = add(5);
add5(3); // 8
```

Caching function results to avoid repeated calculations.

```javascript
function memoize(fn) {
  const cache = {};
  return function(...args) {
    const key = JSON.stringify(args);
    if (key in cache) return cache[key];
    return cache[key] = fn(...args);
  };
}
```

Delaying function execution until after specified time has passed since last invocation.

```javascript
function debounce(fn, delay) {
  let timer;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}
```

Limiting function execution to once per specified time period.

```javascript
function throttle(fn, delay) {
  let lastCall = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastCall >= delay) {
      lastCall = now;
      fn(...args);
    }
  };
}
```

Mechanism that handles asynchronous operations by managing call stack, callback queue, and microtask queue.

```javascript
console.log(1);
setTimeout(() => console.log(2), 0);
Promise.resolve().then(() => console.log(3));
console.log(4);
// Output: 1, 4, 3, 2
```

Function that can pause and resume execution using `yield`.

```javascript
function* numbers() {
  yield 1;
  yield 2;
  yield 3;
}
const gen = numbers();
gen.next().value; // 1
gen.next().value; // 2
```

Object with `next()` method that returns `{value, done}`.

```javascript
const arr = [1, 2, 3];
const iterator = arr[Symbol.iterator]();
iterator.next(); // {value: 1, done: false}
```

Unique and immutable primitive value used as object property key.

```javascript
const sym1 = Symbol('id');
const sym2 = Symbol('id');
sym1 === sym2; // false
```

Map with weak references to keys (objects only), allowing garbage collection.

```javascript
const wm = new WeakMap();
let obj = {};
wm.set(obj, "value");
obj = null; // obj can be garbage collected
```

Set with weak references to objects, allowing garbage collection.

```javascript
const ws = new WeakSet();
let obj = {};
ws.add(obj);
obj = null; // obj can be garbage collected
```

Object that intercepts and customizes operations on another object.

```javascript
const handler = {
  get(target, prop) {
    return prop in target ? target[prop] : "default";
  }
};
const proxy = new Proxy({}, handler);
proxy.x; // "default"
```

Creates scope for object properties. Avoid: confusing, slow, deprecated in strict mode.

```javascript
// Don't use
with (Math) {
  console.log(PI); // 3.14159...
}
```

Function that takes function as argument or returns function.

```javascript
const withLogging = (fn) => (...args) => {
  console.log("calling function");
  return fn(...args);
};
```

Combining functions to create new function.

```javascript
const compose = (f, g) => x => f(g(x));
const add1 = x => x + 1;
const mult2 = x => x * 2;
const add1ThenMult2 = compose(mult2, add1);
add1ThenMult2(5); // 12
```

Design pattern using closures to create private variables.

```javascript
const counter = (function() {
  let count = 0;
  return {
    increment: () => ++count,
    getCount: () => count
  };
})();
```

Native module system using `import` and `export`.

```javascript
// math.js
export const add = (a, b) => a + b;

// app.js
import { add } from './math.js';
```

- Default: one per module, import without braces
- Named: multiple per module, import with braces

```javascript
// default
export default function() {}
import myFunc from './module.js';

// named
export const x = 1;
import { x } from './module.js';
```

Function that processes template literal.

```javascript
function tag(strings, ...values) {
  return strings[0] + values[0].toUpperCase();
}
const name = "john";
tag`Hello ${name}`; // "Hello JOHN"
```

Copies properties from source objects to target.

```javascript
const target = { a: 1 };
const source = { b: 2 };
Object.assign(target, source); // { a: 1, b: 2 }
```
